                            for x in self.threads.values():
                                self.resync(x)
                            cands = sorted(((self.C(x, x.sheets[0]["terms"]), x) for x in self.threads.values()
                                            if x.status not in ENDED and x.sheets and must_haves_ok(self.case, x.sheets[0]["terms"], x.std)),
                                           key=lambda z: z[0])
